const mergePremiumGridSettingsForSharedBoard = (baseSettings = {}, overrideSettings = {}) => {
  const output = {
    ...baseSettings
  }

  Object.entries(overrideSettings || {}).forEach(([key, value]) => {
    if (
      value &&
      typeof value === 'object' &&
      !Array.isArray(value) &&
      output[key] &&
      typeof output[key] === 'object' &&
      !Array.isArray(output[key])
    ) {
      output[key] = mergePremiumGridSettingsForSharedBoard(output[key], value)
    } else if (value !== undefined) {
      output[key] = value
    }
  })

  return output
}


/**
 * V2.3 第 473 批：verify-serial 真 API 測試 helper 安全包裝
 * 只提供 commonGrid=1 測試區手動測試使用，不影響正式頁與 legacyGrid fallback。
 */
const getPremiumGridVerifySerialEndpoint473 = (campaignId) => {
  const safeCampaignId = encodeURIComponent(String(campaignId || '').trim())
  return `/api/draw-engine/campaigns/${safeCampaignId}/verify-serial`
}

const getPremiumGridLocalAuthToken473 = () => {
  if (typeof localStorage === 'undefined') return ''

  return (
    localStorage.getItem('token') ||
    localStorage.getItem('authToken') ||
    localStorage.getItem('accessToken') ||
    localStorage.getItem('mgp_token') ||
    ''
  )
}

const verifyPremiumGridSerialCode = async (campaignId, serialCode) => {
  const endpoint = getPremiumGridVerifySerialEndpoint473(campaignId)
  const token = getPremiumGridLocalAuthToken473()
  const payload = {
    serialCode: String(serialCode || '').trim(),
    code: String(serialCode || '').trim(),
    gameType: 'GRID',
    source: 'commonGrid=1',
    trafficSource: getRouteTrafficSource(),
    tenantSlug: tenantSlug.value || '',
    frontUrl: typeof window !== 'undefined' ? window.location.href : ''
  }

  const response = await fetch(endpoint, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      ...(token ? { Authorization: `Bearer ${token}` } : {})
    },
    body: JSON.stringify(payload)
  })

  const rawText = await response.text()
  const data = rawText ? safeJsonParse(rawText, { message: rawText }) : {}

  if (!response.ok) {
    const error = new Error(data?.message || `verify-serial API 測試失敗：HTTP ${response.status}`)
    error.response = {
      status: response.status,
      data
    }
    throw error
  }

  return unwrapApiData(data)
}

const normalizeTrafficSource = (value = '') => {
  const source = String(value || '').trim().toLowerCase()

  if (source === 'fb') return 'facebook'
  if (source === 'ig') return 'instagram'
  if (['line', 'facebook', 'instagram', 'direct'].includes(source)) return source

  return source || 'direct'
}

const getRouteTrafficSource = () => {
  return normalizeTrafficSource(route.query.from || route.query.source || 'direct')
}

const normalizeCampaignStatus = (value = '') => {
