      shortName: draftPrize.shortName || draftPrize.title || draftPrize.name || gridItems.value[index].shortName,
      quantity: draftPrize.quantity ?? gridItems.value[index].quantity,
      weight: draftPrize.probabilityPercent ?? draftPrize.weight ?? gridItems.value[index].weight,
