const applyAdminPreviewDraftToCampaign = () => {
  if (typeof window === 'undefined') return false
  if (route.query.adminPreviewDraft !== '1') return false

  const draftKey = String(route.query.draftKey || '')
  if (!draftKey) return false

  try {
    const rawDraft = window.localStorage.getItem(draftKey)
    if (!rawDraft) return false

    const draft = JSON.parse(rawDraft)
    // 第 82401～82800 批修正：
    // 舊版平台模板草稿曾直接存 settings；新版 iframe 草稿存 { settings }。
    // 兩種格式都要能讀，避免儲存 / 重新整理後字體大小與獎項尺寸回到預設值。
    const draftSettings = draft?.settings || draft || {}
    const mappedSettings = normalizeAdminPreviewDraftSettings(draftSettings)

    Object.entries(mappedSettings.campaign).forEach(([key, value]) => {
      if (value !== undefined && value !== null && key in campaign) {
        campaign[key] = value
      }
    })

    Object.assign(adminPreviewTextSize, {
      ...adminPreviewTextSize,
      ...(mappedSettings.textSize || {})
    })

    applyAdminPreviewPrizeDraftToGrid(mappedSettings.prizes)

    // 第 80401～80800 批：正式 iframe 預覽會先讀遠端活動 / GameConfig，
    // 遠端資料載入完成後必須再次套用後台草稿，避免文字又被資料庫舊值覆蓋。
    return true
  } catch (error) {
    console.warn('讀取九宮格後台即時預覽草稿失敗：', error)
    return false
  }
}

const applyAdminPreviewDraftPayloadToCampaign = (draft = {}) => {
  // 第 82401～82800 批修正：postMessage 可能傳 { settings }，也可能傳純 settings。
  const draftSettings = draft?.settings || draft || {}
  const mappedSettings = normalizeAdminPreviewDraftSettings(draftSettings)

  Object.entries(mappedSettings.campaign).forEach(([key, value]) => {
    if (value !== undefined && value !== null && key in campaign) {
      campaign[key] = value
    }
  })

  Object.assign(adminPreviewTextSize, {
    ...adminPreviewTextSize,
    ...(mappedSettings.textSize || {})
  })

  applyAdminPreviewPrizeDraftToGrid(mappedSettings.prizes)
  return true
}

const handlePremiumGridAdminDraftMessage = (event) => {
  if (typeof window === 'undefined') return
  if (route.query.adminPreviewDraft !== '1') return
  if (event.origin !== window.location.origin) return
  if (event.data?.type !== 'MGP_PREMIUM_GRID_ADMIN_DRAFT_UPDATE') return

  const routeDraftKey = String(route.query.draftKey || '')
  const eventDraftKey = String(event.data?.draftKey || '')
  if (routeDraftKey && eventDraftKey && routeDraftKey !== eventDraftKey) return

  const payload = event.data?.payload || {}
  if (!payload || typeof payload !== 'object') return

  applyAdminPreviewDraftPayloadToCampaign(payload)
}


const player = reactive({
  chances: 97,
  sharedCount: 0
})

const serialVerify = reactive({
  code: '',
  verified: false,
  verifying: false,
  message: '',
  error: '',
  serialCodeId: null,
  remainingChance: 0
})

const normalizedSerialCode = computed(() => {
  return String(serialVerify.code || '').trim().replace(/\s+/g, '').toUpperCase()
})

const normalizeSerialRemainingChance = (data = {}) => {
  const source = data || {}
  const serialCode = source.serialCode || source.serial || source.serialStatus || {}
  const result = source.result || {}

  const rawValue =
    source.remainingChance ??
    source.remainingSerialChances ??
    source.remainingUses ??
    source.remainingUse ??
    serialCode.remainingChance ??
    serialCode.remainingSerialChances ??
    serialCode.remainingUses ??
    serialCode.remainingUse ??
    result.remainingChance ??
    result.remainingSerialChances ??
    result.remainingUses ??
    result.remainingUse ??
    source.rewardChance ??
    serialCode.rewardChance ??
    result.rewardChance ??
    source.availableChance ??
    source.availableUses ??
    source.totalLimit ??
    source.dailyLimit ??
    1

  const value = Number(rawValue)

  if (!Number.isFinite(value) || value < 0) return 0

  return Math.max(0, value)
}

// 第 31101～31500 批：九宮格玩家狀態保存 alias。
// 舊批次有些地方使用 savePremiumGridState / savePremiumGridGameState，
// 新批次序號同步使用 savePremiumGridPlayerState。
// 這裡統一補安全 alias，避免驗證成功後因函式不存在而中斷。
const savePremiumGridPlayerState = () => {
  try {
    if (typeof savePremiumGridState === 'function') {
      savePremiumGridState()
      return
    }

    if (typeof savePremiumGridGameState === 'function') {
      savePremiumGridGameState()
      return
    }

    if (typeof savePremiumGridLocalState === 'function') {
      savePremiumGridLocalState()
      return
    }

    if (typeof savePlayerState === 'function') {
      savePlayerState()
    }
  } catch (error) {
    console.warn('保存九宮格玩家狀態失敗，已略過：', error)
  }
}

const buildGridSerialChanceMessage = (remainingChance = 0) => {
  const chance = Math.max(0, Number(remainingChance || 0))

  return `序號可使用，剩餘 ${chance} 次。`
}

const syncGridChancesFromSerial = (remainingChance = 1, options = {}) => {
  const rawChance = Number(remainingChance)
  const normalizedChance = Number.isFinite(rawChance) ? Math.max(0, rawChance) : 1
  serialVerify.remainingChance = normalizedChance
  player.chances = normalizedChance

  if (serialVerify.verified || options.forceMessage) {
    serialVerify.message = options.message || buildGridSerialChanceMessage(normalizedChance)
  }

  updateChanceText()
  savePremiumGridPlayerState()
}

const consumeGridSerialChance = (usedCount = 1) => {
  if (!shouldRequireSerialCode.value || !serialVerify.verified) return

  const nextChance = Math.max(0, Number(serialVerify.remainingChance || player.chances || 0) - usedCount)
  serialVerify.remainingChance = nextChance
  player.chances = nextChance
  updateChanceText()
  savePremiumGridPlayerState()
}

const setGridSerialChanceAfterPlay = (apiRemainingChance = null, beforeChance = null) => {
  const before = Number(beforeChance ?? serialVerify.remainingChance ?? player.chances ?? 0)
  const apiValue = Number(apiRemainingChance)

  // 有些後端會回傳 play 前的 remainingChance，例如仍是 99。
  // 如果 API 回傳值沒有變小，就以前端保守扣 1 次，避免畫面卡在 99 或被舊 chances 歸零。
  if (Number.isFinite(apiValue) && apiValue >= 0 && apiValue < before) {
    syncGridChancesFromSerial(apiValue, {
      message: buildGridSerialChanceMessage(apiValue)
    })
    return
  }

  const fallbackChance = Math.max(0, before - 1)

  syncGridChancesFromSerial(fallbackChance, {
    message: buildGridSerialChanceMessage(fallbackChance)
  })
}

const shouldRequireSerialCode = computed(() => {
  return route.query.adminPreviewDraft !== '1'
})

// 第 31101～31500 批：補回真正缺失的定義。
// 上一批有把畫面與邏輯改成使用 effectiveGridChances / postGridJson，
// 但實際檔案沒有成功插入這兩個 const，導致 ReferenceError。
const effectiveGridChances = computed(() => {
  if (shouldRequireSerialCode.value && !serialVerify.verified) {
    return 0
  }

  if (shouldRequireSerialCode.value && serialVerify.verified) {
    return Math.max(0, Number(serialVerify.remainingChance || 0))
  }

  return Math.max(0, Number(player.chances || 0))
})

const frontGridChanceText = computed(() => {
  if (shouldRequireSerialCode.value && !serialVerify.verified) {
    return '請先輸入商家提供的序號'
  }

  return `還有 ${effectiveGridChances.value} 次抽獎機會`
})

const GRID_API_BASE_URL = String(import.meta.env.VITE_API_BASE_URL || 'http://localhost:3000/api').replace(/\/$/, '')

const unwrapGridApiPayload = (payload) => {
  return payload?.data?.data ?? payload?.data ?? payload ?? null
}

const postGridJson = async (path, body = {}) => {
  const endpoint = `${GRID_API_BASE_URL}${path.startsWith('/') ? path : `/${path}`}`
  const response = await fetch(endpoint, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(body)
  })

  const payload = await response.json().catch(() => ({}))

  if (!response.ok) {
    const error = new Error(payload?.message || `API 回應失敗：HTTP ${response.status}`)
    error.responsePayload = payload
    error.status = response.status
    throw error
  }

  return payload
}

const canStartGridDraw = computed(() => {
  if (!shouldRequireSerialCode.value) return canDraw.value

  if (isTenantPremiumGridMode.value) {
    return Boolean(
      serialVerify.verified &&
        normalizedSerialCode.value &&
        effectiveGridChances.value > 0 &&
        !isDrawing.value &&
        !hasTenantPremiumGridBlock.value
    )
  }

  const baseReady = Boolean(
    serialVerify.verified &&
      normalizedSerialCode.value &&
      effectiveGridChances.value > 0 &&
      !isDrawing.value &&
      !tenantPremiumGridLoading.value &&
      !tenantPremiumGridError.value &&
      !hasTenantPremiumGridBlock.value
  )

  if (!baseReady) return false

  return availablePrizeCount.value > 0
})

const verifySerialCode = async () => {
  serialVerify.error = ''
  serialVerify.message = ''

  if (!normalizedSerialCode.value) {
    serialVerify.error = '請先輸入商家提供的序號。'
    return
  }

  serialVerify.verifying = true

  try {
    const campaignId = tenantCampaignId.value || route.query.campaignId || route.query.id || campaign.id
    if (!campaignId) {
      serialVerify.error = '找不到活動 ID，請確認玩家連結是否由活動列表產生。'
      return
    }

    const responsePayload = await postGridJson(`/draw-engine/campaigns/${campaignId}/verify-serial`, {
      code: normalizedSerialCode.value,
      serialCode: normalizedSerialCode.value,
      gameType: 'GRID',
      tenantSlug: tenantSlug.value,
      source: 'formal-premium-grid-player'
    })

    const payload = unwrapGridApiPayload(responsePayload) || {}

    if (payload.valid === false || payload.success === false || responsePayload.success === false) {
      serialVerify.verified = false
      serialVerify.error = payload.message || responsePayload.message || '序號驗證失敗，請確認序號是否正確。'
      return
    }

    serialVerify.verified = true
    serialVerify.serialCodeId = payload.serialCodeId || payload.id || payload.serialCode?.id || null
    syncGridChancesFromSerial(normalizeSerialRemainingChance(payload))
    serialVerify.message = payload.message || responsePayload.message || `序號驗證成功，可使用 ${serialVerify.remainingChance} 次。`
  } catch (error) {
    console.error('九宮格序號驗證失敗:', error)
    serialVerify.verified = false
    serialVerify.error = error?.responsePayload?.message || error?.response?.data?.message || error?.message || '序號驗證失敗，請確認後端 API 是否啟動。'
  } finally {
    serialVerify.verifying = false
  }
}

watch(
  () => serialVerify.code,
  () => {
    if (!serialVerify.verified) return

    serialVerify.verified = false
    serialVerify.message = ''
    serialVerify.error = ''
  }
)

