const normalizeColorValue = (value, fallback) => {
  const text = String(value || '').trim()
  const withoutHash = text.startsWith('#') ? text.slice(1) : text

  if (/^[0-9a-fA-F]{6}$/.test(withoutHash)) {
    return `#${withoutHash.toUpperCase()}`
  }

  return fallback
}

