const isSharedGridBoardDryRun = computed(() => {
  return isSharedGridBoardDryRunQueryEnabled()
})

const isSharedGridBoardCanary = computed(() => {
  if (typeof window === 'undefined') return false

  const params = new URLSearchParams(window.location.search)

  return params.get('sharedGridCanary') === '1' &&
    params.get('legacyGrid') !== '1' &&
    params.get('commonGrid') !== '1'
})

const sharedGridBoardRouteMatrix = computed(() => {
  if (typeof window === 'undefined') {
    return {
      legacyGrid: false,
      commonGrid: false,
      sharedGridBoard: false,
      effectiveMode: 'ssr-safe'
    }
  }

  const params = new URLSearchParams(window.location.search)
  const legacyGrid = params.get('legacyGrid') === '1'
  const commonGrid = params.get('commonGrid') === '1'
  const sharedGridBoard = params.get('sharedGridBoard') === '1'
  const sharedGridCanary = params.get('sharedGridCanary') === '1'
  const originalGrid = params.get('originalGrid') === '1'

  let effectiveMode = 'formal-original'

  if (legacyGrid) {
    effectiveMode = 'legacy-grid-fallback'
  } else if (commonGrid) {
    effectiveMode = 'common-grid-test-area'
  } else if (sharedGridCanary) {
    effectiveMode = 'shared-grid-board-canary'
  } else if (sharedGridBoard) {
    effectiveMode = 'shared-grid-board-dry-run'
  } else if (originalGrid) {
    effectiveMode = 'formal-original-check'
  }

  return {
    legacyGrid,
    commonGrid,
    sharedGridBoard,
    sharedGridCanary,
    originalGrid,
    effectiveMode
  }
})

