  return Boolean(
    isDrawing.value ||
      drawPerformancePhase.value === 'tap-received' ||
      drawPerformancePhase.value === 'submitting' ||
      drawPerformancePhase.value === 'spinning'
  )
})

const gridStartButtonLabel = computed(() => {
  if (drawPerformancePhase.value === 'tap-received') return '已收到，準備抽獎...'
  if (drawPerformancePhase.value === 'submitting') return '抽獎送出中...'
  if (drawPerformancePhase.value === 'spinning' || isDrawing.value) return '抽選中，請稍候...'

  return drawButtonText.value
})

const frontGridRecordRows = computed(() => {
  return drawLogs.value.slice(0, 5).map((log, index) => ({
    id: log.id || `grid-record-${index}`,
    icon: log.icon || '🎁',
    prizeName: log.prizeName || log.name || log.title || '抽獎紀錄',
    resultText: log.isWin === false ? '未中獎' : '中獎',
    serialCode: log.serialCode || log.code || normalizedSerialCode.value || '—',
    createdAt: log.createdAt || log.time || ''
  }))
})

const isGridPrizeRevealed = (item = {}, index = -1) => {
  if (item?.isButton) return true
  if (isAdminMode.value) return true

  // 第 47601～48000 批：
  // 跑燈抽選中不能提前露出格子內真正獎項。
  // 只有抽選完成、resultPrize 寫入後，最後中獎格才揭曉。
  const prize = resultPrize.value

  if (!prize || isDrawing.value) return false

  return String(prize.id || '') === String(item.id || '') || String(prize.name || '') === String(item.name || '')
}

