const sleep = (time) => {
  return new Promise((resolve) => {
    setTimeout(resolve, time)
  })
}

const gridSpinTuning = {
  minRounds: 9,
  extraRounds: 3,
  startDelay: 42,
  cruiseDelay: 64,
  endDelay: 240,
  settleDelay: 420,
  tickVolume: 0.045,
  finishVolume: 0.09
}

let gridAudioContext = null

const getGridAudioContext = () => {
  if (typeof window === 'undefined') return null

  const AudioContextConstructor = window.AudioContext || window.webkitAudioContext

  if (!AudioContextConstructor) return null

  if (!gridAudioContext) {
    gridAudioContext = new AudioContextConstructor()
  }

  if (gridAudioContext.state === 'suspended') {
    gridAudioContext.resume().catch(() => {})
  }

  return gridAudioContext
}

const playGridTone = ({
  frequency = 640,
  duration = 0.045,
  volume = gridSpinTuning.tickVolume,
  type = 'square'
} = {}) => {
  try {
    const audioContext = getGridAudioContext()

    if (!audioContext) return

    const oscillator = audioContext.createOscillator()
    const gain = audioContext.createGain()
    const now = audioContext.currentTime

    oscillator.type = type
    oscillator.frequency.setValueAtTime(frequency, now)

    gain.gain.setValueAtTime(0.0001, now)
    gain.gain.exponentialRampToValueAtTime(Math.max(0.0001, volume), now + 0.008)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + duration)

    oscillator.connect(gain)
    gain.connect(audioContext.destination)
    oscillator.start(now)
    oscillator.stop(now + duration + 0.012)
  } catch (error) {
    // 音效只做玩家體驗強化，瀏覽器不支援時不可影響抽獎流程。
  }
}

const playGridTickSound = (step = 0, progress = 0) => {
  const baseFrequency = progress > 0.82 ? 520 : progress > 0.55 ? 610 : 720
  const frequency = baseFrequency + ((step % 3) * 22)

  playGridTone({
    frequency,
    duration: progress > 0.82 ? 0.065 : 0.042,
    volume: progress > 0.82 ? 0.055 : gridSpinTuning.tickVolume,
    type: 'square'
  })
}

const playGridFinishSound = () => {
  playGridTone({
    frequency: 880,
    duration: 0.09,
    volume: gridSpinTuning.finishVolume,
    type: 'triangle'
  })

  setTimeout(() => {
    playGridTone({
      frequency: 1174,
      duration: 0.11,
      volume: gridSpinTuning.finishVolume,
      type: 'triangle'
    })
  }, 88)
}

const vibrateGridDevice = (pattern = 12) => {
  if (typeof navigator === 'undefined' || typeof navigator.vibrate !== 'function') return

  try {
    navigator.vibrate(pattern)
  } catch (error) {
    // 手機震動不支援時略過。
  }
}

const easeOutCubic = (value) => {
  return 1 - Math.pow(1 - value, 3)
}

const getGridSpinDelay = (step, totalSteps) => {
  const progress = totalSteps <= 1 ? 1 : step / (totalSteps - 1)

  if (progress < 0.22) {
    return gridSpinTuning.startDelay + Math.round(progress * 42)
  }

  if (progress < 0.66) {
    return gridSpinTuning.cruiseDelay + Math.round(Math.sin(progress * Math.PI) * 14)
  }

  const slowProgress = (progress - 0.66) / 0.34

  return gridSpinTuning.cruiseDelay + Math.round(easeOutCubic(slowProgress) * (gridSpinTuning.endDelay - gridSpinTuning.cruiseDelay))
}

const getGridSpinPhaseMessage = (progress) => {
  if (progress < 0.24) return '九宮格開始高速跑燈，幸運格正在啟動。'
  if (progress < 0.66) return '跑燈持續加強中，系統正在抽選獎項。'
  if (progress < 0.9) return '跑燈逐步減速，準備停在本次結果。'

  return '最後確認中，請稍候揭曉獎項。'
}

const runPremiumGridSpinAnimation = async (targetIndex) => {
  const normalizedTargetIndex = Number.isInteger(targetIndex) && targetIndex >= 0
    ? targetIndex
    : drawPath[drawPath.length - 1]

  const targetPathIndex = drawPath.findIndex((index) => index === normalizedTargetIndex)
  const safeTargetPathIndex = targetPathIndex >= 0 ? targetPathIndex : drawPath.length - 1
  const baseRounds = gridSpinTuning.minRounds + Math.floor(Math.random() * (gridSpinTuning.extraRounds + 1))
  const totalSteps = baseRounds * drawPath.length + safeTargetPathIndex + 1

  drawPerformancePhase.value = 'spinning'

  for (let step = 0; step < totalSteps; step += 1) {
    const progress = totalSteps <= 1 ? 1 : step / (totalSteps - 1)
    activeIndex.value = drawPath[step % drawPath.length]
    drawPerformanceMessage.value = getGridSpinPhaseMessage(progress)

    playGridTickSound(step, progress)

    if (step % 5 === 0) {
      vibrateGridDevice(progress > 0.82 ? [10, 18, 10] : 8)
    }

    await sleep(getGridSpinDelay(step, totalSteps))
  }

  activeIndex.value = normalizedTargetIndex
  drawPerformancePhase.value = 'settled'
  drawPerformanceMessage.value = '抽選完成，正在開啟中獎結果。'
  playGridFinishSound()
  vibrateGridDevice([18, 24, 18])
  await sleep(gridSpinTuning.settleDelay)
}

const showStorageMessage = (message) => {
  storageMessage.value = message

  setTimeout(() => {
    storageMessage.value = ''
  }, 2400)
}

const updateChanceText = () => {
  if (shouldRequireSerialCode.value && !serialVerify.verified) {
    campaign.chanceText = '請先輸入商家提供的序號'
    return
  }

  const displayChance = shouldRequireSerialCode.value && serialVerify.verified
    ? serialVerify.remainingChance
    : player.chances

  campaign.chanceText = `還有 ${Math.max(0, Number(displayChance || 0))} 次抽獎機會`
}


const normalizeTenantCampaignList = (response) => {
  const payload = unwrapApiData(response)

  if (Array.isArray(payload)) return payload
  if (Array.isArray(payload?.items)) return payload.items
  if (Array.isArray(payload?.campaigns)) return payload.campaigns
  if (Array.isArray(payload?.data)) return payload.data

  return payload ? [payload] : []
}

const getPrizeIconByType = (prize = {}) => {
  const type = String(prize.type || '').toUpperCase()
  const title = String(prize.title || prize.name || '')

  if (type === 'LOSE') return '💫'
  if (title.includes('咖啡')) return '☕'
  if (title.includes('折') || title.includes('券')) return '🎟️'
  if (title.includes('金') || title.includes('獎')) return '🏆'

  return '🎁'
}

const applyTenantPremiumGridCampaign = (campaignData = {}) => {
  tenantPremiumGridCampaign.value = campaignData

  campaign.brandName = campaignData?.tenant?.name || campaignData?.tenantName || campaign.brandName
  campaign.pageTitle = campaignData?.title || '精緻九宮格抽獎'
  campaign.mainTitle = campaignData?.title || '精緻九宮格抽獎'
  campaign.subTitle = campaignData?.description || '商家專屬九宮格活動'
  campaign.heroTagline = normalizeCampaignStatus(campaignData?.status) === 'ACTIVE' ? '活動進行中' : '商家專屬活動'
  campaign.logoText = String(campaign.brandName || 'P').slice(0, 1).toUpperCase()
  campaign.noticeText = '本活動由商家後台建立，玩家紀錄會自動歸屬目前商家。'

  const prizes = Array.isArray(campaignData?.prizes) ? campaignData.prizes.slice(0, 8) : []

  if (prizes.length) {
    gridItems.value = defaultGridItems.map((item, index) => {
      if (item.isButton) return item

      const prize = prizes[index]

      if (!prize) {
        return {
          ...item,
          weight: 0,
          quantity: 0
        }
      }

      return {
        ...item,
        id: prize.id || item.id,
        name: prize.title || prize.name || item.name,
        shortName: prize.shortName || prize.title || prize.name || item.shortName,
        icon: prize.icon || getPrizeIconByType(prize),
        imageUrl: prize.imageUrl || '',
        weight: Number(prize.probability || prize.weight || 0),
        quantity: Number(prize.remainStock ?? prize.quantity ?? 0),
        backendPrize: prize
      }
    })
  }

  if (!serialVerify.verified) {
    player.chances = Number(campaignData?.dailyLimit || campaignData?.totalLimit || player.chances || 1)
  }
  updateChanceText()
  tenantPremiumGridLoadedAt.value = new Date().toLocaleString('zh-TW')
}

const loadTenantPremiumGridCampaign = async () => {
  if (!isTenantPremiumGridMode.value) return

  tenantPremiumGridLoading.value = true
  tenantPremiumGridError.value = ''

  try {
    const response = await getTenantPremiumGridCampaignApi(tenantSlug.value)
    const campaigns = normalizeTenantCampaignList(response)
    const activeCampaign = campaigns.find((item) => String(item?.gameType || '').toUpperCase() === 'GRID') || campaigns[0]

    if (!activeCampaign?.id) {
      tenantPremiumGridCampaign.value = null
      tenantPremiumGridError.value = '目前商家尚未建立精緻九宮格活動，請聯絡平台管理員建立 GRID 活動。'
      return
    }

    applyTenantPremiumGridCampaign(activeCampaign)
    await loadPremiumGridGameConfigSettings(activeCampaign.id)
    applyAdminPreviewDraftToCampaign()
  } catch (error) {
    console.error('載入商家精緻九宮格活動失敗：', error)
    tenantPremiumGridCampaign.value = null
    tenantPremiumGridError.value = '載入商家精緻九宮格活動失敗，請稍後再試。'
  } finally {
    tenantPremiumGridLoading.value = false
  }
}


const normalizePremiumGridPrizeProbability = (prize = {}) => {
  return Number(prize.probabilityPercent ?? prize.probability ?? prize.weight ?? prize.chance ?? 0)
}

const applyPremiumGridGameConfigSettingsToLiveState = (settings = {}) => {
  if (!settings || typeof settings !== 'object') return

  const prizeSettings = Array.isArray(settings.prizes)
    ? settings.prizes
    : (Array.isArray(settings.gridItems) ? settings.gridItems : [])

  if (prizeSettings.length) {
    gridItems.value = defaultGridItems.map((item, index) => {
      if (item.isButton) return item

      const prize = prizeSettings[index]

      if (!prize || prize.enabled === false || prize.isEnabled === false) {
        return {
          ...item,
          weight: 0,
          probabilityPercent: 0,
          quantity: 0
        }
      }

      const probability = normalizePremiumGridPrizeProbability(prize)

      return {
        ...item,
        id: prize.id || item.id,
        name: prize.title || prize.name || item.name,
        title: prize.title || prize.name || item.title || item.name,
        shortName: prize.shortName || prize.title || prize.name || item.shortName,
        icon: prize.icon || prize.emoji || item.icon,
        imageUrl: prize.imageUrl || prize.image || prize.prizeImageUrl || '',
        weight: probability,
        probabilityPercent: probability,
        quantity: Number(prize.quantity ?? prize.remainStock ?? prize.stock ?? item.quantity ?? 0),
        backendPrize: prize,
        backendProbabilitySource: 'GAME_CONFIG_SETTINGS'
      }
    })
  }

  const basic = settings.basicText || {}
  if (basic.pageTitle) campaign.pageTitle = basic.pageTitle
  if (basic.brandName) campaign.brandName = basic.brandName
  if (basic.headline) campaign.mainTitle = basic.headline
  if (basic.subtitle) campaign.subTitle = basic.subtitle
  if (basic.badgeText) campaign.heroTagline = basic.badgeText
  if (basic.playButtonText) campaign.buttonText = basic.playButtonText

  if (settings.display?.chanceText) campaign.chanceText = settings.display.chanceText

  Object.assign(adminPreviewTextSize, {
    ...adminPreviewTextSize,
    ...normalizePremiumGridTextSizeSettings(settings)
  })

  updateChanceText()
  applyAdminPreviewDraftToCampaign()
}

const premiumGridBackendProbabilitySummary = computed(() => {
  const items = gridItems.value.filter((item) => !item.isButton && item.enabled !== false && Number(item.weight || 0) > 0)
  const total = items.reduce((sum, item) => sum + Number(item.weight || 0), 0)

  return {
    source: isTenantPremiumGridMode.value ? 'BACKEND_DRAW_ENGINE' : 'LOCAL_PREVIEW_ONLY',
    sourceLabel: isTenantPremiumGridMode.value
      ? '正式玩家結果由後端 Draw Engine 依後台百分比計算'
      : '目前是模板 / 本機預覽，才使用前端試算',
    totalProbability: Number(total.toFixed(2)),
    itemCount: items.length,
    campaignId: tenantCampaignId.value || remoteGridCampaignId.value || ''
  }
})

const shouldLoadPlatformPremiumGridTemplate = computed(() => {
  return !isTenantPremiumGridMode.value && !tenantCampaignId.value && route.query.adminPreviewDraft !== '1'
})

const loadPlatformPremiumGridTemplateSettings = async () => {
  if (!shouldLoadPlatformPremiumGridTemplate.value) return

  premiumGridGameConfigLoading.value = true
  premiumGridGameConfigError.value = ''

  try {
    const response = await http.get('/campaigns', {
      params: {
        slug: PLATFORM_PREMIUM_GRID_TEMPLATE_SLUG,
        gameType: 'GRID'
      }
    })

    const list = normalizeApiList(unwrapApiPayload(response))
    const templateCampaign = list.find((item) => String(item?.slug || '') === PLATFORM_PREMIUM_GRID_TEMPLATE_SLUG) || list[0] || null
    const settings = templateCampaign?.gameConfig?.settings || templateCampaign?.settings || templateCampaign?.gameConfig?.data?.settings || null

    if (settings && typeof settings === 'object') {
      applyPremiumGridGameConfigSettingsToLiveState(settings)
      campaign.templateSource = 'PLATFORM_PREMIUM_GRID_TEMPLATE_DATABASE'
      campaign.templateSourceLabel = '已讀取線上九宮格平台模板'
      premiumGridGameConfigLoadedAt.value = new Date().toLocaleString('zh-TW', { hour12: false })
    }
  } catch (error) {
    console.warn('讀取九宮格平台模板設定失敗，改用預設模板：', error)
    premiumGridGameConfigError.value = error?.response?.data?.message || ''
  } finally {
    premiumGridGameConfigLoading.value = false
    applyAdminPreviewDraftToCampaign()
  }
}

const loadPremiumGridGameConfigSettings = async (campaignId) => {
  // 第 30701～31100 批：
  // 正式遠端玩家頁也要讀 PostgreSQL GameConfig.settings，
  // 不能只在 sharedGridBoard dry-run 才讀。
  if (!campaignId) return

  premiumGridGameConfigLoading.value = true
  premiumGridGameConfigError.value = ''

  try {
    const response = await getCampaignGameConfigApi(campaignId)
    const settings = unwrapGameConfigSettings(response)

    premiumGridGameConfigSettings.value = settings && Object.keys(settings).length ? settings : null

    if (premiumGridGameConfigSettings.value) {
      applyPremiumGridGameConfigSettingsToLiveState(premiumGridGameConfigSettings.value)
    }

    premiumGridGameConfigLoadedAt.value = new Date().toLocaleString('zh-TW')
    applyAdminPreviewDraftToCampaign()
  } catch (error) {
    console.error('載入九宮格 GameConfig settings 失敗：', error)
    premiumGridGameConfigSettings.value = null
    premiumGridGameConfigError.value = error?.response?.data?.message || '載入九宮格設定失敗，已使用頁面預設設定。'
  } finally {
    premiumGridGameConfigLoading.value = false
  }
}

const playTenantPremiumGridDraw = async () => {
  if (!tenantCampaignId.value) return null

  const beforeChance = Number(serialVerify.remainingChance || player.chances || 0)

  const response = await playDrawEngineCampaignApi(tenantCampaignId.value, {
    gameType: 'GRID',
    requireSerialCode: true,
    serialCode: normalizedSerialCode.value,
    code: normalizedSerialCode.value,
    source: getRouteTrafficSource(),
    trafficSource: getRouteTrafficSource(),
    tenantSlug: tenantSlug.value,
    frontUrl: getShareUrl(),
    resultPayload: {
      source: getRouteTrafficSource(),
      tenantSlug: tenantSlug.value,
      frontUrl: getShareUrl(),
      template: 'premium-grid',
      probabilitySource: 'GAME_CONFIG_SETTINGS',
      probabilityMode: 'BACKEND_DRAW_ENGINE'
    }
  })

  const payload = unwrapApiData(response)
  const result = payload?.result || payload
  const serialData = payload.serialCode || payload.serial || payload.serialStatus || result.serialCode || payload.playRecord?.serialCode || {}
  const apiRemainingChance =
    serialData.remainingChance ??
    serialData.remainingSerialChances ??
    serialData.remainingUses ??
    payload.remainingChance ??
    payload.remainingSerialChances ??
    payload.remainingUses ??
    result.remainingChance ??
    result.remainingSerialChances ??
    result.remainingUses ??
    null

  setGridSerialChanceAfterPlay(apiRemainingChance, beforeChance)

  const selectedPrizeId = result?.prizeId || payload?.prize?.id || payload?.playRecord?.prizeId
  const selectedPrizeTitle = result?.prizeTitle || payload?.prize?.title || payload?.playRecord?.prize?.title || ''

  tenantPremiumGridLastDraw.value = payload

  const matchedPrize = gridItems.value.find((item) => {
    if (item.isButton) return false

    return String(item.id) === String(selectedPrizeId) || String(item.name) === String(selectedPrizeTitle)
  })

  if (matchedPrize) {
    return {
      ...matchedPrize,
      backendProbabilitySource: result?.prizeSource || payload?.result?.prizeSource || 'DRAW_ENGINE',
      backendProbabilityMode: 'BACKEND_DRAW_ENGINE'
    }
  }

  const apiPrize = payload?.prize || result?.prize || payload?.playRecord?.prize || {}
  const apiPrizeTitle = selectedPrizeTitle || apiPrize.title || apiPrize.name

  if (apiPrizeTitle) {
    return {
      id: selectedPrizeId || apiPrize.id || `remote-grid-result-${Date.now()}`,
      name: apiPrizeTitle,
      shortName: apiPrize.shortName || apiPrizeTitle,
      icon: apiPrize.icon || apiPrize.emoji || '🎁',
      imageUrl: apiPrize.imageUrl || '',
      weight: Number(apiPrize.weight || apiPrize.probability || 1),
      quantity: Number(apiPrize.quantity || apiPrize.stock || 9999),
      backendPrize: apiPrize,
      backendProbabilitySource: result?.prizeSource || payload?.result?.prizeSource || 'DRAW_ENGINE',
      backendProbabilityMode: 'BACKEND_DRAW_ENGINE'
    }
  }

  return null
}

const applyGameSettingsToCampaign = () => {
  const game = currentGame.value

  if (!game) return

  campaign.pageTitle = game.name || campaign.pageTitle
  campaign.mainTitle = game.name || campaign.mainTitle
  campaign.subTitle = game.description || campaign.subTitle
  campaign.heroTagline = game.subtitle || campaign.heroTagline
  campaign.logoText = game.icon || campaign.logoText
  if (!serialVerify.verified) {
    player.chances = Number(game.playLimit || player.chances || 1)
  }
  updateChanceText()

  if (Array.isArray(game.prizes) && game.prizes.length) {
    const prizes = game.prizes.slice(0, 8)

    gridItems.value = defaultGridItems.map((item, index) => {
      if (item.isButton) return item

      const prize = prizes[index]

      if (!prize) return item

      return {
        ...item,
        id: prize.id || item.id,
        name: prize.name || item.name,
        shortName: prize.shortName || prize.name || item.shortName,
        icon: prize.icon || item.icon,
        imageUrl: prize.imageUrl || '',
        weight: Number(prize.weight || item.weight || 0),
        quantity: Number(prize.quantity || item.quantity || 0)
      }
    })
  }
}

const getPrizePool = () => {
  return gridItems.value.filter((item) => {
    return !item.isButton && Number(item.quantity || 0) > 0 && Number(item.weight || 0) > 0
  })
}

const pickPrize = () => {
  const prizePool = getPrizePool()

  if (!prizePool.length) return null

  const totalWeight = prizePool.reduce((sum, item) => {
    return sum + Number(item.weight || 0)
  }, 0)

  let randomValue = Math.random() * totalWeight

  return prizePool.find((item) => {
    randomValue -= Number(item.weight || 0)
    return randomValue <= 0
  }) || prizePool[prizePool.length - 1]
}

const getPremiumGridStorageKey = () => {
  return `${PREMIUM_GRID_STORAGE_KEY}_${currentGameId.value}`
}

const broadcastPremiumGridStateChange = () => {
  // 不再對同一個頁面發送自訂事件，避免 watch -> save -> load -> save 形成迴圈。
  // 不同分頁會透過瀏覽器 storage 事件同步。
}

const pingPremiumGridSync = () => {
  if (typeof localStorage === 'undefined') return

  localStorage.setItem(
    PREMIUM_GRID_SYNC_PING_KEY,
    JSON.stringify({
      key: getPremiumGridStorageKey(),
      gameId: currentGameId.value,
      updatedAt: new Date().toISOString()
    })
  )
}

const syncPremiumGridToPlayer = () => {
  savePremiumGridState()
  pingPremiumGridSync()

  lastSyncAt.value = new Date().toLocaleString('zh-TW')
  lastSyncMessage.value = `已同步到玩家版：${sourcePath.value}`

  showStorageMessage('已同步最新九宮格設定到玩家版。')
}

const handlePremiumGridStorageSync = (event) => {
  if (!event) return
  if (isSavingPremiumGridState.value) return

  if (event.key === getPremiumGridStorageKey()) {
    loadPremiumGridState()
    return
  }

  if (event.key === PREMIUM_GRID_SYNC_PING_KEY) {
    const payload = safeJsonParse(event.newValue, null)

    if (payload?.key === getPremiumGridStorageKey()) {
      lastSyncAt.value = new Date().toLocaleString('zh-TW')
      lastSyncMessage.value = '已收到管理版同步，玩家畫面已更新。'
      loadPremiumGridState()
    }
  }
}

const handlePremiumGridCustomSync = (event) => {
  if (!event?.detail || event.detail.key !== getPremiumGridStorageKey()) return
  if (isSavingPremiumGridState.value) return

  loadPremiumGridState()
}

const savePremiumGridState = () => {
  if (isTenantPremiumGridMode.value && !isAdminMode.value) return
  if (typeof localStorage === 'undefined') return
  if (isApplyingPremiumGridRemoteState.value) return

  isSavingPremiumGridState.value = true

  const payload = {
    campaign: cloneByJson(campaign),
    player: cloneByJson(player),
    gridItems: cloneByJson(gridItems.value),
    drawLogs: cloneByJson(drawLogs.value),
    ui: {
      showThemeTools: showThemeTools.value,
      showThemeGuide: showThemeGuide.value
    },
    savedAt: new Date().toISOString()
  }

  localStorage.setItem(getPremiumGridStorageKey(), JSON.stringify(payload))
  pingPremiumGridSync()

  setTimeout(() => {
    isSavingPremiumGridState.value = false
  }, 0)
}

const loadPremiumGridState = () => {
  if (isTenantPremiumGridMode.value) {
    loadTenantPremiumGridCampaign()
    return
  }

  if (typeof localStorage === 'undefined') return

  isApplyingPremiumGridRemoteState.value = true

  const payload = safeJsonParse(
    localStorage.getItem(getPremiumGridStorageKey()),
    null
  )

  if (!payload) {
    applyGameSettingsToCampaign()
    isApplyingPremiumGridRemoteState.value = false
    return
  }

  Object.assign(campaign, {
    ...defaultCampaignSnapshot,
    ...(payload.campaign || {})
  })

  Object.assign(player, {
    ...defaultPlayerSnapshot,
    ...(payload.player || {})
  })

  if (Array.isArray(payload.gridItems) && payload.gridItems.length) {
    gridItems.value = payload.gridItems
  }

  if (Array.isArray(payload.drawLogs)) {
    drawLogs.value = payload.drawLogs.slice(0, 8)
  }

  if (typeof payload.ui?.showThemeTools === 'boolean') {
    showThemeTools.value = payload.ui.showThemeTools
  }

  if (typeof payload.ui?.showThemeGuide === 'boolean') {
    showThemeGuide.value = payload.ui.showThemeGuide
  }

  updateChanceText()

  setTimeout(() => {
    isApplyingPremiumGridRemoteState.value = false
  }, 0)
}

const clearPremiumGridState = () => {
  const confirmed = window.confirm('確定要清除精緻九宮格本機保存資料，並還原示範狀態嗎？')

  if (!confirmed) return

  localStorage.removeItem(`${PREMIUM_GRID_STORAGE_KEY}_${currentGameId.value}`)

  Object.assign(campaign, cloneByJson(defaultCampaignSnapshot))
  Object.assign(player, cloneByJson(defaultPlayerSnapshot))
  gridItems.value = cloneByJson(defaultGridItemsSnapshot)
  activeIndex.value = -1
  resultPrize.value = null
  showResultModal.value = false
  drawLogs.value = []
  showThemeTools.value = true
  showThemeGuide.value = true

  applyGameSettingsToCampaign()
  updateChanceText()
  showStorageMessage('已清除保存資料，並還原示範狀態。')
}

const getSavedStateText = () => {
  if (typeof localStorage === 'undefined') return '尚未保存'

  const payload = safeJsonParse(
    localStorage.getItem(`${PREMIUM_GRID_STORAGE_KEY}_${currentGameId.value}`),
    null
  )

  if (!payload?.savedAt) return '尚未保存'

  const date = new Date(payload.savedAt)

  if (Number.isNaN(date.getTime())) return '已保存'

  return date.toLocaleString('zh-TW', {
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit'
  })
}

const downloadTextFile = (filename, content, mimeType = 'text/plain;charset=utf-8') => {
  const blob = new Blob([content], {
    type: mimeType
  })

  const url = URL.createObjectURL(blob)
  const link = document.createElement('a')

  link.href = url
  link.download = filename
  link.style.display = 'none'

  document.body.appendChild(link)
  link.click()
  document.body.removeChild(link)

  setTimeout(() => {
    URL.revokeObjectURL(url)
  }, 1000)
}

const getExportTimeText = () => {
  const date = new Date()

  const year = date.getFullYear()
  const month = String(date.getMonth() + 1).padStart(2, '0')
  const day = String(date.getDate()).padStart(2, '0')
  const hour = String(date.getHours()).padStart(2, '0')
  const minute = String(date.getMinutes()).padStart(2, '0')
  const second = String(date.getSeconds()).padStart(2, '0')

  return `${year}${month}${day}_${hour}${minute}${second}`
}

const exportPremiumGridState = () => {
