/**
 * V2.3 第 468-472 批：正式頁 commonGrid=1 測試區 CommonGamePlayBoard 顯示回歸與互動提示強化
 * 從真實 PremiumGridLotteryView.vue 重新接入，不覆蓋原本正式畫面。
 */
const premiumGridCommonFormalSafetySummary = computed(() => {
  try {
    return getPremiumGridFormalSafetySummary()
  } catch (error) {
    console.warn('[PremiumGrid] common formal safety summary failed:', error)

    return {
      allCriticalPassed: false,
      readyForFormalPageChange: false,
      readyForNextReadBatch: false,
      conclusion: '共用模組安全檢查讀取失敗，維持原正式頁顯示。'
    }
  }
})

const premiumGridFormalQueryParams = computed(() => {
  try {
    return new URLSearchParams(window.location.search || '')
  } catch (error) {
    console.warn('[PremiumGrid] query params parse failed:', error)
    return new URLSearchParams('')
  }
})

const isPremiumGridLegacyGridForced = computed(() => {
  return premiumGridFormalQueryParams.value.get('legacyGrid') === '1'
})

const isPremiumGridCommonGridRequested = computed(() => {
  return premiumGridFormalQueryParams.value.get('commonGrid') === '1'
})

const isPremiumGridCommonModuleSafetyReady = computed(() => {
  return Boolean(premiumGridCommonFormalSafetySummary.value?.allCriticalPassed)
})

const shouldKeepPremiumGridLegacyFallback = computed(() => {
  return true
})

const usePremiumGridCommonModuleSafeFlag = computed(() => {
  return Boolean(
    isPremiumGridCommonGridRequested.value &&
      !isPremiumGridLegacyGridForced.value &&
      isPremiumGridCommonModuleSafetyReady.value
  )
})

/**
 * Multi Game Platform V2.3 第 618-622 批：正式頁共用模組 controlled live 顯示結果驗收版
 *
 * 修正第 578-582 批正式頁 render 時引用 isCommonGridPreviewRoute / premiumGridCommonRouteSafety
 * 但檔案內沒有定義造成 ReferenceError 的問題。
 * 這裡只補相容 alias，不推進正式套用，不改 router / DB / 抽獎核心。
 */
const isCommonGridPreviewRoute = computed(() => {
  return Boolean(isPremiumGridCommonGridRequested.value)
})

const premiumGridCommonRouteSafety = computed(() => {
  return {
    safeToRenderCommonGrid: Boolean(usePremiumGridCommonModuleSafeFlag.value),
    commonGridRequested: isPremiumGridCommonGridRequested.value,
    legacyGridForced: isPremiumGridLegacyGridForced.value,
    safetyReady: isPremiumGridCommonModuleSafetyReady.value,
    note: usePremiumGridCommonModuleSafeFlag.value
      ? 'commonGrid=1 測試區安全條件通過。'
      : 'commonGrid=1 測試區未通過安全條件，或目前不是 commonGrid 測試路由。'
  }
})

