const premiumGridCommonPlayBoardEventLog468 = ref([])

const recordPremiumGridCommonPlayBoardEvent468 = (type, template) => {
  const payload = {
    id: `${type}-${Date.now()}`,
    type,
    batch: 'V2.3 第 468-472 批',
    mode: usePremiumGridCommonModuleSafeFlag.value ? 'commonGrid=1' : 'formal-default',
    requestWillBeSent: false,
    callsApi: false,
    writesDb: false,
    title: template?.label || template?.title || premiumGridFormalCommonTemplate.value?.label || 'CommonGamePlayBoard 測試事件',
    createdAt: new Date().toLocaleString('zh-TW')
  }

  premiumGridCommonPlayBoardEventLog468.value = [
    payload,
    ...premiumGridCommonPlayBoardEventLog468.value
  ].slice(0, 5)

  showStorageMessage(`共用 PlayBoard 測試事件：${type}，目前不送出 API。`)
  console.log('[PremiumGrid formal common PlayBoard test event]', payload, template)
}

