const premiumGridVerifySerialManualBlockedReasons = computed(() => {
  const reasons = []

  if (!isPremiumGridCommonGridRequested.value) {
    reasons.push('目前不是 commonGrid=1 測試模式。')
  }

  if (isPremiumGridLegacyGridForced.value) {
    reasons.push('目前是 legacyGrid=1 fallback 模式。')
  }

  if (!premiumGridVerifySerialEditableForm.value.campaignIdReady) {
    reasons.push('campaignId 格式尚未通過。')
  }

  if (!premiumGridVerifySerialEditableForm.value.serialCodeReady) {
    reasons.push('serialCode 格式尚未通過。')
  }

  if (!premiumGridVerifySerialManualConfirmState.value) {
    reasons.push('尚未勾選手動確認。')
  }

  if (!enableCommonGridApiPreview.value) {
    reasons.push('enableCommonGridApiPreview 仍固定 false。')
  }

  reasons.push('第 390 批測試按鈕固定 disabled，仍禁止呼叫 API。')

  return reasons
})

