/**
 * V2.3 第 478-482 批：verify-serial 結果狀態接入 playControl 測試區解鎖預備
 * 第 478 批：verify response normalized state 版
 * 第 479 批：playControl 測試區解鎖 guard 版
 * 第 480 批：CommonGamePlayBoard props unlock preview 版
 * 第 481 批：play event 仍 preview-only 保護版
 * 第 482 批：解鎖預備穩定備份版
 *
 * 本批只把 verify-serial 成功結果轉成 commonGrid=1 測試區的 playControl 解鎖預備狀態。
 * play API 仍不送出、DB 仍不寫入、router / 抽獎核心不修改、正式頁與 legacyGrid fallback 保留。
 */
const normalizePremiumGridVerifySerialPayload478 = (payload = {}) => {
  const root = payload?.result ?? payload?.data ?? payload
  const nested = root?.data ?? root?.result ?? root
  const validFlag = Boolean(
    nested?.valid === true ||
    nested?.ok === true ||
    nested?.success === true ||
    nested?.status === 'UNUSED' ||
    nested?.status === 'VALID' ||
    nested?.status === 'VERIFIED'
  )
  const statusText = String(
    nested?.status ||
    nested?.serialStatus ||
    nested?.codeStatus ||
    (validFlag ? 'VERIFIED' : 'UNKNOWN')
  ).toUpperCase()

  return {
    raw: payload,
    root,
    nested,
    ok: Boolean(payload?.ok === true || root?.ok === true || nested?.ok === true || validFlag),
    valid: validFlag,
    status: statusText,
    message: nested?.message || root?.message || payload?.message || (validFlag ? '序號驗證成功，可進入測試區解鎖預備。' : '尚未取得有效序號驗證結果。'),
    campaignId: nested?.campaignId || root?.campaignId || payload?.campaignId || premiumGridVerifySerialEditableForm.value.campaignId,
    serialCode: nested?.serialCode || nested?.code || root?.serialCode || payload?.serialCode || premiumGridVerifySerialEditableForm.value.serialCode,
    remainingTimes: Number(nested?.remainingTimes ?? nested?.remainingAttempts ?? nested?.remaining ?? 0),
    rewardPreview: nested?.reward || nested?.prize || root?.reward || root?.prize || null
  }
}

