    ok: Boolean(normalized.ok || payload?.success === true || root?.success === true || result?.success === true),
    status: String(result?.status || root?.status || normalized.status || 'PLAY_API_TESTED').toUpperCase(),
    message: result?.message || root?.message || normalized.message || 'play API 測試區已收到回應。',
