    premiumGridPlayApiLastStableError494.value = normalizedError
    premiumGridPlayApiRealSendError488.value = normalizedError.message
    recordPremiumGridCommonPlayBoardEvent468('play-api-real-send-error', template)
    showStorageMessage('play API 測試送出失敗，請查看錯誤訊息。')
  } finally {
