const getPremiumGridPlayApiResultUiTone493 = (result, errorMessage = '') => {
  if (errorMessage) return 'error'
  if (!result) return 'idle'
  if (result.ok === true) return 'success'
  if (String(result.status || '').includes('ERROR')) return 'error'

  return 'warning'
}

const normalizePremiumGridPlayApiError494 = (error) => {
  const responseData = error?.response?.data || null
  const nestedData = responseData?.data || null
  const statusCode = error?.response?.status || responseData?.statusCode || ''
  const code = responseData?.code || nestedData?.code || error?.code || 'PLAY_API_TEST_ERROR'
  const message = responseData?.message || nestedData?.message || error?.message || 'play API 測試送出失敗。'

  return {
    ok: false,
    status: 'PLAY_API_TEST_ERROR',
    statusCode,
    code,
    message,
    hint: statusCode === 401
      ? '請確認目前登入狀態與 Bearer token。'
      : (statusCode === 403
        ? '請確認目前帳號是否有參加或測試權限。'
        : (statusCode === 404
          ? '請確認 campaignId / tenantSlug / endpoint 是否正確。'
          : '請查看後端 console 與 Network response，確認錯誤來源。')),
    canRetry: ![400, 401, 403, 404].includes(Number(statusCode)),
    raw: responseData || String(error?.message || error || ''),
    occurredAt: new Date().toISOString(),
    occurredAtText: new Date().toLocaleString('zh-TW'),
    commonGridOnly: true,
    formalPageProtected: true,
    legacyFallbackProtected: true
  }
}

