/**
 * V2.3 第 458-462 批：verify-serial API 手動測試安全包裝
 * 本批建立真正 API 呼叫函式的安全包裝，但 enableCommonGridApiPreview 仍固定 false。
 * 因此正常情況下按鈕仍 disabled，不會呼叫 API。
 */
const premiumGridVerifySerialApiTestLoading = ref(false)
const premiumGridVerifySerialApiTestResult = ref(null)
const premiumGridVerifySerialApiTestError = ref('')
const premiumGridVerifySerialApiTestLastRunAt = ref('')

const premiumGridVerifySerialApiTestGuard = computed(() => {
  const campaignReady = premiumGridVerifySerialEditableForm.value.campaignIdReady
  const serialReady = premiumGridVerifySerialEditableForm.value.serialCodeReady
  const manualConfirmed = premiumGridVerifySerialManualConfirmState.value
  const localSwitchOn = premiumGridVerifySerialLocalTestSwitch.value
  const commonGridReady = isPremiumGridCommonGridRequested.value
  const legacyBlocked = isPremiumGridLegacyGridForced.value
  const apiPreviewReady = enableCommonGridApiPreview.value || enableCommonGridVerifySerialApiSafetySwitch473.value

  const blockedReasons = []

  if (!commonGridReady) blockedReasons.push('不是 commonGrid=1 測試模式。')
  if (legacyBlocked) blockedReasons.push('目前是 legacyGrid=1 fallback。')
  if (!campaignReady) blockedReasons.push('campaignId 格式未通過。')
  if (!serialReady) blockedReasons.push('serialCode 格式未通過。')
  if (!manualConfirmed) blockedReasons.push('尚未勾選手動確認。')
  if (!localSwitchOn) blockedReasons.push('尚未開啟 local-only 測試開關。')
  if (!apiPreviewReady) blockedReasons.push('請在 commonGrid=1 測試網址額外加上 verifyApi=1，或保持 enableCommonGridApiPreview=true。')
  if (premiumGridVerifySerialApiTestLoading.value) blockedReasons.push('目前已有 verify-serial 測試執行中。')

  return {
    batch: 'V2.3 第 458-462 批',
    title: '精緻九宮格 commonGrid=1 測試區 CommonGamePlayBoard props 實際綁定實作預備版',
    commonGridReady,
    legacyBlocked,
    campaignReady,
    serialReady,
    manualConfirmed,
    localSwitchOn,
    apiPreviewReady,
    loading: premiumGridVerifySerialApiTestLoading.value,
    canCallApi: blockedReasons.length === 0,
    requestWillBeSent: blockedReasons.length === 0,
    blockedReasons,
    endpoint: premiumGridVerifySerialEditableForm.value.endpoint,
    campaignId: premiumGridVerifySerialEditableForm.value.campaignId,
    serialCode: premiumGridVerifySerialEditableForm.value.serialCode
  }
})


