const resetPremiumGridVerifySerialApiTestState = () => {
  premiumGridVerifySerialApiTestResult.value = null
  premiumGridVerifySerialApiTestError.value = ''
  premiumGridVerifySerialApiTestLastRunAt.value = ''
}

const handlePremiumGridVerifySerialManualTest = async () => {
  const guard = premiumGridVerifySerialApiTestGuard.value

  premiumGridVerifySerialApiTestError.value = ''

  if (!guard.canCallApi) {
    premiumGridVerifySerialApiTestError.value = `目前禁止呼叫 verify-serial：${guard.blockedReasons.join(' / ')}`
    return
  }

  try {
    premiumGridVerifySerialApiTestLoading.value = true
    premiumGridVerifySerialApiTestResult.value = null
    premiumGridVerifySerialApiTestLastRunAt.value = new Date().toISOString()

    const result = await verifyPremiumGridSerialCode(
      guard.campaignId,
      guard.serialCode
    )

    premiumGridVerifySerialApiTestResult.value = {
      ok: true,
      source: 'verifyPremiumGridSerialCode',
      campaignId: guard.campaignId,
      serialCode: guard.serialCode,
      result
    }
  } catch (error) {
    console.error('[PremiumGrid] verify serial manual test failed:', error)

    premiumGridVerifySerialApiTestError.value =
      error?.response?.data?.message ||
      error?.message ||
      'verify-serial API 測試失敗'

    premiumGridVerifySerialApiTestResult.value = {
      ok: false,
      source: 'verifyPremiumGridSerialCode',
      campaignId: guard.campaignId,
      serialCode: guard.serialCode,
      error: premiumGridVerifySerialApiTestError.value
    }
  } finally {
    premiumGridVerifySerialApiTestLoading.value = false
  }
}

