const premiumGridVerifySerialResultDisplayPreview = computed(() => {
  const result = premiumGridVerifySerialApiTestResult.value
  const error = premiumGridVerifySerialApiTestError.value
  const loading = premiumGridVerifySerialApiTestLoading.value
  const guard = premiumGridVerifySerialApiTestGuard.value || {}

  if (loading) {
    return {
      state: 'loading',
      icon: '⏳',
      title: 'verify-serial 測試中',
      message: '正在等待後端回應。第 396 批正常情況下不會進入此狀態，除非後續批次開啟 API preview。',
      tone: 'sky',
      canProceedToPlay: false,
      raw: null
    }
  }

  if (error) {
    return {
      state: 'error',
      icon: '❌',
      title: 'verify-serial 測試失敗',
      message: error,
      tone: 'rose',
      canProceedToPlay: false,
      raw: result
    }
  }

  if (result?.ok) {
    return {
      state: 'success',
      icon: '✅',
      title: 'verify-serial 測試成功',
      message: '序號驗證回傳成功。注意：第 396 批只做顯示版型，仍不進入 play API。',
      tone: 'emerald',
      canProceedToPlay: false,
      raw: result
    }
  }

  if (guard?.blockedReasons?.length) {
    return {
      state: 'blocked',
      icon: '🔒',
      title: 'verify-serial 目前被安全 Guard 阻擋',
      message: '這是正常的安全狀態；enableCommonGridApiPreview 仍固定 false，所以不會呼叫 API。',
      tone: 'amber',
      canProceedToPlay: false,
      raw: {
        blockedReasons: guard.blockedReasons
      }
    }
  }

  return {
    state: 'idle',
    icon: '🧪',
    title: '尚未執行 verify-serial 測試',
    message: '第 396 批只建立結果顯示版型，不會主動呼叫 verify API。',
    tone: 'slate',
    canProceedToPlay: false,
    raw: null
  }
})

