/**
 * V2.3 第 458-462 批：verify-serial 結果接入 CommonGamePlayBoard 狀態預備
 * 本批只把 verify result display 轉成 PlayBoard 可讀狀態，不呼叫 API、不進入 play。
 */
const premiumGridVerifySerialCommonPlayBoardState = computed(() => {
  const display = premiumGridVerifySerialResultDisplayPreview.value || {}
  const raw = display.raw?.result || display.raw || {}
  const status = String(raw?.status || raw?.data?.status || '').toUpperCase()
  const valid = raw?.valid === true || raw?.data?.valid === true || raw?.success === true

  let playBoardState = 'idle'
  let canPlay = false
  let blocked = true
  let message = display.message || '尚未執行 verify-serial 測試。'

  if (display.state === 'loading') {
    playBoardState = 'verifying'
    blocked = true
    canPlay = false
    message = '序號驗證中，暫不可遊玩。'
  } else if (display.state === 'success' || valid) {
    playBoardState = 'verified'
    blocked = false
    canPlay = false
    message = '序號驗證成功；第 398 批只建立狀態，不進入 play API。'
  } else if (display.state === 'error') {
    playBoardState = 'verify_error'
    blocked = true
    canPlay = false
    message = display.message || '序號驗證失敗。'
  } else if (display.state === 'blocked') {
    playBoardState = 'guard_blocked'
    blocked = true
    canPlay = false
    message = '目前被安全 Guard 阻擋，未呼叫 verify API。'
  } else if (['USED', 'INVALID', 'EXPIRED'].includes(status)) {
    playBoardState = `serial_${status.toLowerCase()}`
    blocked = true
    canPlay = false
    message = `序號狀態：${status}，不可遊玩。`
  }

  return {
    batch: 'V2.3 第 458-462 批',
    title: '精緻九宮格 commonGrid=1 測試區 CommonGamePlayBoard props 實際綁定實作預備版',
    sourceState: display.state || 'idle',
    playBoardState,
    valid,
    status: status || 'PREVIEW_ONLY',
    canPlay,
    blocked,
    verified: playBoardState === 'verified',
    canProceedToPlayApi: false,
    message,
    rawPreview: raw,
    safety: {
      apiPreviewEnabled: enableCommonGridApiPreview.value,
      requestWillBeSent: false,
      callsVerifyApi: false,
      callsPlayApi: false,
      writesDb: false,
      changesRouter: false,
      changesDrawCore: false,
      keepsLegacyFallback: true
    }
  }
})

