/**
 * V2.3 第 458-462 批：verify-serial 狀態驅動 PlayBoard 操作提示
 * 本批只根據 verify → PlayBoard 狀態顯示操作提示。
 * 不呼叫 API、不進入 play、不寫 DB。
 */
const premiumGridVerifySerialPlayBoardOperationHint = computed(() => {
  const state = premiumGridVerifySerialCommonPlayBoardState.value || {}
  const playBoardState = state.playBoardState || 'idle'

  const base = {
    batch: 'V2.3 第 458-462 批',
    playBoardState,
    canPlay: false,
    canCallPlayApi: false,
    showPlayButton: false,
    playButtonDisabled: true,
    apiPreviewEnabled: enableCommonGridApiPreview.value,
    requestWillBeSent: false
  }

  if (playBoardState === 'verified') {
    return {
      ...base,
      tone: 'emerald',
      icon: '✅',
      title: '序號驗證已通過',
      message: '序號狀態已可對應為 verified；但第 400 批仍不開放 play API，只顯示下一步提示。',
      primaryActionLabel: '下一步：可準備開始遊戲（目前未開放）',
      secondaryActionLabel: '重新檢查序號狀態',
      guidance: [
        '後續才會把 verified 狀態轉成真正可遊玩。',
        '目前 canPlay 仍固定 false。',
        'playPremiumGridDraw() 尚未接入。',
        '不會消耗遊玩次數。'
      ]
    }
  }

  if (playBoardState === 'verify_error') {
    return {
      ...base,
      tone: 'rose',
      icon: '❌',
      title: '序號驗證失敗',
      message: state.message || '請確認序號格式或測試資料是否正確。',
      primaryActionLabel: '重新輸入序號',
      secondaryActionLabel: '檢查 campaignId',
      guidance: [
        '錯誤狀態不可進入 play。',
        '請重新檢查 campaignId / serialCode。',
        '錯誤 response 不應扣次數。',
        '本批仍不呼叫 API。'
      ]
    }
  }

  if (['serial_used', 'serial_invalid', 'serial_expired'].includes(playBoardState)) {
    const labels = {
      serial_used: '序號已使用',
      serial_invalid: '序號無效',
      serial_expired: '序號已過期'
    }

    return {
      ...base,
      tone: 'amber',
      icon: '⚠️',
      title: labels[playBoardState] || '序號不可使用',
      message: state.message || '目前序號狀態不可進入遊戲。',
      primaryActionLabel: '更換序號',
      secondaryActionLabel: '聯繫活動管理員',
      guidance: [
        '不可用序號必須阻擋 play。',
        '不可寫入中獎紀錄。',
        '不可消耗遊玩次數。',
        '可提示玩家重新輸入或聯繫管理員。'
      ]
    }
  }

  if (playBoardState === 'verifying') {
    return {
      ...base,
      tone: 'sky',
      icon: '⏳',
