  const canaryRender = premiumGridFormalCanaryActualCommonModuleRender535.value
  const legacyForced = Boolean(isPremiumGridLegacyGridForced.value)
  const commonGridRequested = Boolean(isPremiumGridCommonGridRequested.value)

  let displayMode = 'formal-original-default'
  let routeDecision = '正式頁預設仍使用原本九宮格。'

  if (legacyForced) {
    displayMode = 'legacy-fallback-original'
    routeDecision = 'legacyGrid=1 最高優先，強制回到原正式九宮格。'
  } else if (commonGridRequested) {
    displayMode = 'common-grid-test-area'
    routeDecision = 'commonGrid=1 維持測試區，不和正式候選路線混用。'
  } else if (candidate.candidateAllowedForInspection) {
    displayMode = canaryRender?.renderMode || 'formal-canary-candidate-preview'
    routeDecision = '候選路線只顯示共用模組候選與保護檢查，不改正式預設。'
  }

  return {
    title: 'default candidate route resolver 版',
    batch: 'V2.3 第 554 批',
    displayMode,
    routeDecision,
    candidateAllowedForInspection: candidate.candidateAllowedForInspection,
    formalDefaultShouldSwitchNow: false,
    formalDefaultStillOriginal: true,
    legacyFallbackHighestPriority: true,
    commonGridTestStillAvailable: true,
    canaryRenderMode: canaryRender?.renderMode || 'formal-original',
    originalFormalFallbackAvailable: true
  }
})

