const premiumGridFormalControlledDefaultApplyFlag558 = computed(() => {
  const candidateBackup = premiumGridFormalDefaultCandidateStableBackup557.value
  const controlledRequested = Boolean(isPremiumGridFormalControlledDefaultApplyRequested558.value)
  const candidateRequested = Boolean(isPremiumGridFormalDefaultCandidateRequested553.value)
  const finalGateRequested = Boolean(isPremiumGridFormalFinalGateRequested548.value)
  const legacyForced = Boolean(isPremiumGridLegacyGridForced.value)
  const commonGridRequested = Boolean(isPremiumGridCommonGridRequested.value)

  const controlledApplyAllowed = Boolean(
    controlledRequested &&
      candidateRequested &&
      finalGateRequested &&
      candidateBackup.defaultSwitchCandidateReady &&
      candidateBackup.legacyFallbackHighestPriority &&
      candidateBackup.originalFormalFallbackAvailable &&
      isPremiumGridCommonModuleSafetyReady.value &&
      !legacyForced &&
      !commonGridRequested
  )

  return {
    title: 'formal controlled default apply flag 版',
    batch: 'V2.3 第 558 批',
    controlledRequested,
    candidateRequested,
    finalGateRequested,
    legacyForced,
    commonGridRequested,
    controlledApplyAllowed,
    formalDefaultCandidateReady: Boolean(candidateBackup.defaultSwitchCandidateReady),
    legacyFallbackHighestPriority: true,
    originalFormalFallbackAvailable: true,
    formalDefaultCanRenderCommonModuleWithFlag: controlledApplyAllowed,
    formalDefaultPermanentSwitch: false,
    candidateUrl: `${sourcePath.value}?formalDryRun=1&formalCommon=1&formalGray=1&formalCanary=1&formalApply=1&formalFinalGate=1&formalDefaultCandidate=1&formalControlledApply=1`,
    fallbackUrl: `${sourcePath.value}?formalDryRun=1&formalCommon=1&formalGray=1&formalCanary=1&formalApply=1&formalFinalGate=1&formalDefaultCandidate=1&formalControlledApply=1&legacyGrid=1`
  }
})

const premiumGridFormalControlledDefaultApplyRouteResolver559 = computed(() => {
  const controlled = premiumGridFormalControlledDefaultApplyFlag558.value
  const canaryResolver = premiumGridFormalCanaryDisplayModeResolver534.value

  let displayMode = 'formal-original-default'
  let renderCommonModule = false
  let routeDecision = '正式頁預設仍使用原本九宮格。'

  if (isPremiumGridLegacyGridForced.value) {
    displayMode = 'legacy-fallback-original'
    renderCommonModule = false
    routeDecision = 'legacyGrid=1 最高優先，強制回到原正式九宮格。'
  } else if (isPremiumGridCommonGridRequested.value) {
    displayMode = 'common-grid-test-area'
    renderCommonModule = true
    routeDecision = 'commonGrid=1 維持獨立測試區。'
  } else if (controlled.controlledApplyAllowed) {
    displayMode = 'formal-controlled-default-common-display'
    renderCommonModule = true
    routeDecision = 'controlled apply 條件通過，本次可在正式候選路線顯示 CommonGamePlayBoard。'
  } else if (canaryResolver.renderCommonModule) {
    displayMode = canaryResolver.mode
    renderCommonModule = true
    routeDecision = '仍沿用 canary 實際顯示路線，不進入 controlled default apply。'
  }

  return {
    title: 'controlled apply route resolver 版',
    batch: 'V2.3 第 559 批',
    displayMode,
    renderCommonModule,
    routeDecision,
    controlledApplyAllowed: controlled.controlledApplyAllowed,
    formalDefaultPermanentSwitch: false,
    legacyFallbackHighestPriority: true,
    commonGridTestStillAvailable: true,
    originalFormalFallbackAvailable: true,
    canaryRenderMode: canaryResolver.mode
  }
})

