    },
    {
      id: 'no-permanent-switch',
      label: '尚未永久預設切換',
      expected: '本批仍不能讓正式頁永久預設切到共用模組',
      passed: controlled.formalDefaultPermanentSwitch === false && stable.formalDefaultPermanentSwitch === false,
      note: '保持 controlled apply 為旗標路線，不污染正式預設路徑。'
    },
    {
      id: 'legacy-highest-priority',
      label: 'legacyGrid 最高優先',
      expected: 'legacyGrid=1 不受 controlled apply 影響，必須回到原正式九宮格',
      passed: Boolean(controlled.legacyFallbackHighestPriority && stable.legacyFallbackHighestPriority),
      note: '緊急回退路線仍可直接使用。'
    },
    {
      id: 'common-grid-test-area-available',
      label: 'commonGrid 測試區保留',
      expected: 'commonGrid=1 仍是獨立測試區，不被正式旗標流程覆蓋',
      passed: Boolean(stable.commonGridTestStillAvailable),
      note: '測試區仍可繼續驗證 verify / play / props。'
    },
    {
      id: 'verify-play-guarded',
      label: 'verify / play guard 保留',
      expected: 'verifyApi / playApi / sendPlayApi 仍需明確開關與 guard',
      passed: Boolean(stable.verifyPlayStillGuarded),
      note: '不會因正式套用驗收而放大 API 風險。'
    }
  ]

  const failedItems = acceptanceItems.filter((item) => !item.passed)

  return {
    batch: 'V2.3 第 563 批',
    title: 'controlled apply result acceptance 版',
    acceptanceItems,
    failedCount: failedItems.length,
    allPassed: failedItems.length === 0,
    controlledApplyRenderCommonModule: Boolean(controlled.renderCommonModule),
    formalDefaultPermanentSwitch: false,
