    routeDecision = 'commonGrid=1 測試區維持獨立，不等於正式 live candidate。'
  } else if (candidate.controlledLiveCandidateAllowed && confirmationResolver.keepOriginalFormalFallback) {
    displayMode = 'controlled-live-candidate-common'
    routeDecision = 'formalLiveCandidate=1 與完整前置旗標通過；可顯示 controlled live candidate 共用模組，但 rollback / fallback 仍保留。'
  }

  return {
    batch: 'V2.3 第 614 批',
    title: 'controlled live candidate resolver 版',
    displayMode,
    routeDecision,
    renderCommonModule: displayMode === 'controlled-live-candidate-common',
    keepOriginalFormalFallback: true,
    commonGridTestStillAvailable: true,
    legacyFallbackHighestPriority: true,
    permanentDefaultSwitch: false,
    candidate,
    inheritedFinalConfirmationResolver: {
      displayMode: confirmationResolver.displayMode,
      renderCommonModule: confirmationResolver.renderCommonModule,
      routeDecision: confirmationResolver.routeDecision
    }
  }
})

