                          <p class="text-xs font-black text-slate-800">
                            {{ guide.title }}
                          </p>

                          <p class="mt-1 text-xs font-bold leading-5 text-slate-500">
                            {{ guide.description }}
                          </p>
                        </article>
                      </div>
                    </div>

                    <div
